def shipping_cost(weight_lb, zone, express=False):
    """Return the parcel shipping price in dollars, rounded to cents."""
    import math

    if isinstance(weight_lb, bool) or not isinstance(weight_lb, (int, float)):
        raise ValueError("weight must be a number greater than 0 and at most 70")
    if not math.isfinite(weight_lb) or weight_lb <= 0 or weight_lb > 70:
        raise ValueError("weight must be greater than 0 and at most 70")
    if isinstance(zone, bool) or zone not in (1, 2, 3):
        raise ValueError("unknown zone")

    base, additional_rate = {
        1: (5.00, 1.25),
        2: (7.50, 1.25),
        3: (10.00, 2.00),
    }[zone]
    price = base + max(0, math.ceil(weight_lb) - 1) * additional_rate
    return round(price * (2 if express else 1), 2)
